    # Fixed, conservative strength. There is no plugin-level haptics settings screen.
    _HAPTIC_LEVEL_MULT = (1.0, 1.0, 1.0)

    def _hap_enabled(self):
        """Respect Android's global touch-feedback setting; do not keep a hidden plugin toggle."""
        value = getattr(self, "_hap_on_cache", None)
        if value is None:
            try:
                SettingsSystem = jclass("android.provider.Settings$System")
                ctx = ApplicationLoader.applicationContext
                value = bool(int(SettingsSystem.getInt(
                    ctx.getContentResolver(), "haptic_feedback_enabled", 1)))
            except Exception:
                value = True
            self._hap_on_cache = value
        return bool(value)

    def _hap_level(self):
        return 1

    # ---- capability probe (once per process) ---------------------------------------------

    def _hap_sdk(self):
        value = getattr(self, "_hap_sdk_cache", None)
        if value is None:
            try:
                value = int(jclass("android.os.Build$VERSION").SDK_INT)
            except Exception:
                value = 0
            self._hap_sdk_cache = value
        return value

    _HAP_NO_MOTOR = {"tier": 0, "vib": None, "attrs": None, "prims": (), "amp": False, "size": 8}

    def _hap_caps(self):
        """Resolve the Vibrator and the best tier it can drive. One probe, cached forever:
        nothing here can change while the process lives. The result is published only once it is
        complete, so a second thread never reads a half-built tier."""
        caps = getattr(self, "_hap_caps_cache", None)
        if caps is not None:
            return caps
        caps = dict(self._HAP_NO_MOTOR)
        sdk = self._hap_sdk()
        try:
            ctx = ApplicationLoader.applicationContext
            vib = None
            if sdk >= 31:
                try:
                    manager = ctx.getSystemService("vibrator_manager")
                    if manager is not None:
                        vib = manager.getDefaultVibrator()
                except Exception:
                    vib = None
            if vib is None:
                vib = ctx.getSystemService("vibrator")
            if vib is None or not bool(vib.hasVibrator()):
                self._hap_caps_cache = caps
                return caps
            caps["vib"] = vib
            caps["tier"] = 1 if sdk >= 26 else 0
            try:
                caps["amp"] = bool(vib.hasAmplitudeControl())
            except Exception:
                caps["amp"] = False
            if sdk >= 29:
                caps["tier"] = 2
            if sdk >= 30:
                # arePrimitivesSupported answers for the physical actuator, not the API level:
                # plenty of API 30+ phones report every primitive unsupported.
                try:
                    ids = [self._HP_CLICK, self._HP_THUD, self._HP_SPIN, self._HP_QUICK_RISE,
                           self._HP_SLOW_RISE, self._HP_QUICK_FALL, self._HP_TICK, self._HP_LOW_TICK]
                    flags = vib.arePrimitivesSupported(jarray(jint)(ids))
                    supported = tuple(ids[i] for i in range(len(ids)) if bool(flags[i]))
                    if self._HP_CLICK in supported:
                        caps["prims"] = supported
                        caps["tier"] = 3
                except Exception:
                    pass
                try:
                    size = int(vib.getCompositionSizeMax())
                    if size > 0:
                        caps["size"] = size
                except Exception:
                    pass
            caps["attrs"] = self._hap_attributes(sdk)
        except Exception as e:
            try: self.log("[haptics] probe: " + _cause(e))
            except Exception: pass
        self._hap_caps_cache = caps
        return caps

    def _hap_attributes(self, sdk):
        """Tag the vibration as touch feedback. Without this the OS files our haptics under
        "notifications", so they go quiet the moment the user silences notification vibration —
        which is exactly the wrong behaviour for a button press."""
        try:
            if sdk >= 33:
                VibrationAttributes = jclass("android.os.VibrationAttributes")
                return VibrationAttributes.createForUsage(18)      # USAGE_TOUCH
        except Exception:
            pass
        try:
            AudioAttributes = jclass("android.media.AudioAttributes")
            return (AudioAttributes.Builder()
                    .setUsage(13)          # USAGE_ASSISTANCE_SONIFICATION
                    .setContentType(4)     # CONTENT_TYPE_SONIFICATION
                    .build())
        except Exception:
            return None

    # ---- playback ------------------------------------------------------------------------

    def _hap_post(self, job):
        """vibrate() is a binder round-trip. Short, but it lands on the UI thread at the exact
        moment this plugin works hardest to keep clear, so it runs on one long-lived daemon
        thread. A full queue drops the newest job: a haptic that arrives late is worse than one
        that never played at all."""
        try:
            q = getattr(self, "_hap_queue", None)
            if q is None:
                import queue, threading
                q = self._hap_queue = queue.Queue(maxsize=6)

                def _pump():
                    while True:
                        try:
                            work = q.get()
                            if work is None:
                                return
                            work()
                        except Exception:
                            pass
                worker = threading.Thread(target=_pump, name="chimeranft-haptics")
                worker.daemon = True
                worker.start()
                self._hap_worker = worker
            try:
                q.put_nowait(job)
            except Exception:
                pass
        except Exception:
            pass

    def _hap_primitive(self, pid, supported):
        """Walk an unsupported primitive toward CLICK rather than dropping it: a five-grain
        crunch missing its grains is silence, but the same crunch built from clicks is still
        recognisably a crunch."""
        for _ in range(4):
            if pid in supported:
                return pid
            nxt = self._HP_SUBSTITUTE.get(pid)
            if nxt is None or nxt == pid:
                return None
            pid = nxt
        return pid if pid in supported else None

    def _hap_now(self):
        """Seam for the two throttles below. They are the only time-dependent behaviour in the
        engine, and a caller that cannot move the clock can only observe that they swallow
        everything — which is indistinguishable from a broken engine."""
        import time as _t
        return _t.time()

    def _hap(self, name, view=None, throttle=0.045, essential=False):
        """Play a named pattern. Everything about it is best-effort by design — a device with
        haptics disabled, no actuator or a locked-down ROM simply feels nothing, and no caller
        ever has to care."""
        try:
            if not essential:
                return
            if not self._hap_enabled():
                return
            recipe = self._HAPTICS.get(str(name))
            if recipe is None:
                return
            now = self._hap_now()
            state = getattr(self, "_hap_last", None)
            if state is not None:
                last_name, last_at = state
                # Two of the same pattern inside one gesture read as a rattle, and any two
                # patterns closer than ~14 ms are felt as one smeared buzz.
                if now - last_at < (throttle if last_name == name else 0.014):
                    return
            self._hap_last = (name, now)
            caps = getattr(self, "_hap_caps_cache", None)
            if caps is None:
                # First haptic of the session. The probe is a handful of binder calls, so it runs
                # on the worker as well rather than on the UI thread mid-tap; _hap_play falls back
                # to the view path itself if the probe turns up no actuator.
                self._hap_post(lambda: self._hap_play(recipe, view, self._hap_caps()))
                return
            if caps.get("vib") is None:
                self._hap_view(recipe, view)
                return
            self._hap_post(lambda: self._hap_play(recipe, view, caps))
        except Exception:
            pass

    def _hap_play(self, recipe, view, caps):
        comp, timings, amps, predefined, const = recipe
        vib, attrs = caps.get("vib"), caps.get("attrs")
        mult = self._HAPTIC_LEVEL_MULT[self._hap_level()]
        tier = int(caps.get("tier", 0))
        try:
            VibrationEffect = jclass("android.os.VibrationEffect") if tier >= 1 else None
        except Exception:
            VibrationEffect = None
        effect = None
        try:
            if tier >= 3 and VibrationEffect is not None:
                supported = caps.get("prims") or ()
                composition = VibrationEffect.startComposition()
                used = 0
                for pid, scale, delay in comp[:int(caps.get("size", 8))]:
                    resolved = self._hap_primitive(pid, supported)
                    if resolved is None:
                        continue
                    value = max(0.05, min(1.0, float(scale) * mult))
                    composition.addPrimitive(int(resolved),
                                             jfloat(value) if jfloat is not None else value,
                                             int(delay))
                    used += 1
                if used:
                    effect = composition.compose()
            if effect is None and tier >= 2 and VibrationEffect is not None:
                effect = VibrationEffect.createPredefined(int(predefined))
            if effect is None and tier >= 1 and VibrationEffect is not None and jlong is not None:
                times = jarray(jlong)([int(t) for t in timings])
                if caps.get("amp"):
                    scaled = [min(255, int(a * mult)) if a else 0 for a in amps]
                    effect = VibrationEffect.createWaveform(times, jarray(jint)(scaled), -1)
                else:
                    effect = VibrationEffect.createWaveform(times, -1)
        except Exception:
            effect = None
        try:
            if effect is not None:
                if attrs is not None:
                    vib.vibrate(effect, attrs)
                else:
                    vib.vibrate(effect)
                return
            # Pre-API-26: one blunt pulse as long as the pattern would have been.
            total = min(120, max(10, int(sum(timings) * mult)))
            vib.vibrate(JLong(total).longValue())
        except Exception:
            # SecurityException on a stripped ROM, or a vendor Vibrator that refuses the
            # effect: stop paying for the probe and let the View carry the feedback from here on.
            try:
                self._hap_caps_cache = dict(self._HAP_NO_MOTOR)
            except Exception:
                pass
            self._hap_view(recipe, view)

    def _hap_view(self, recipe, view):
        """Last resort: the View's own constant, downgraded to something the running OS knows."""
        if view is None:
            return
        const = recipe[4]
        since = self._HAPTIC_SINCE.get(const)
        if since is not None and self._hap_sdk() < since:
            const = self._HAPTIC_OLDER.get(const, self._HAPTIC_KEYBOARD_TAP)
        try:
            run_on_ui_thread(lambda: self._haptic(view, const))
        except Exception:
            self._haptic(view, const)

    def _hap_roll(self, total_ms=2600, tail_ms=260):
        """A decelerating ratchet under the upgrade roll. The ticks thin out as the reel slows,
        which is what makes a spin read as a physical thing losing momentum rather than as a
        progress bar. Scheduled in one go: the sheet's animation is a fixed length, so there is
        nothing to follow and no state to keep."""
        try:
            if not self._hap_enabled() or run_on_ui_thread is None:
                return
            at, gap = 0.0, 45.0
            limit = float(total_ms) - float(tail_ms)
            while at < limit and gap < 400.0:
                run_on_ui_thread(lambda: self._hap("tick", throttle=0.02), int(at))
                at += gap
                gap *= 1.16
        except Exception:
            pass

    def _hap_notch(self, token, value, name="notch"):
        """One tick per crossed notch. A SeekBar reports ~60 samples a second; firing on each of
        them is a continuous buzz, and the whole point of a notch is that you can count them."""
        try:
            if not self._hap_ticks_enabled():
                return
            state = getattr(self, "_hap_notches", None)
            if state is None:
                state = self._hap_notches = {}
            if state.get(token) == value:
                return
            state[token] = value
            self._hap(name, throttle=0.016)
        except Exception:
            pass

    def _hap_toggle(self, enabled):
        """A Switch row hands its handler the new value and no view, which is exactly enough: the
        direction of the toggle is the direction of the haptic."""
        self._hap("toggle_on" if enabled else "toggle_off")

    def _hap_result(self, ok, heavy=False):
        """Feedback belongs to the *outcome*, not to the tap. A rejected username and a saved one
        are the same gesture, and the finger is the fastest place to tell them apart."""
        self._hap(("reveal" if heavy else "success") if ok else "error")

    def _haptic(self, view, constant=None):
        """Raw constant path, kept for the few callers that already speak HapticFeedbackConstants.
        Best-effort: a device or ROM with haptics off simply does nothing."""
        if view is None or not self._hap_enabled():
            return
        try:
            code = self._HAPTIC_KEYBOARD_TAP if constant is None else int(constant)
            view.performHapticFeedback(code, self._HAPTIC_FLAGS)
        except Exception:
            pass

    def _click(self, fn, feedback=True, hap=None):
        """Every custom button in the plugin goes through here, so `hap` is how a button says
        what it *is* — «crunch» for the one that deletes, «impact» for the one that saves."""
        plugin = self

        class _C(dynamic_proxy(View.OnClickListener)):
            def onClick(self2, v):
                try:
                    if feedback:
                        plugin._tap_feedback(v)
                    fn(v)
                except Exception as e:
                    plugin._toast("click err: " + repr(e))
        return _C()

    def _argb(self, c):
        try:
            return (0xFF000000 | (int(c) & 0xFFFFFF))
        except Exception:
            return Theme.getColor(Theme.key_windowBackgroundGray)

    def _gift_card(self, ctx, g):
        card = LinearLayout(ctx)
        card.setOrientation(LinearLayout.VERTICAL)
        bg = GradientDrawable()
        bg.setColor(Theme.getColor(Theme.key_dialogBackground))
        bg.setCornerRadius(AndroidUtilities.dp(18))
        card.setBackground(bg)
        try: card.setElevation(float(AndroidUtilities.dp(10)))
        except Exception: pass
        pad = AndroidUtilities.dp(12)
        card.setPadding(pad, pad, pad, pad)
        clp = LinearLayout.LayoutParams(-1, -2)
        clp.bottomMargin = AndroidUtilities.dp(12)
        card.setLayoutParams(clp)

        # top: preview + info
        top = LinearLayout(ctx)
        top.setOrientation(LinearLayout.HORIZONTAL)

        # native preview (same cell as the grid tiles), ribbon stripped (the title shows #num);
        # fall back to our custom preview if the native cell can't be built. Sized like a grid
        # tile (~116dp) so the sticker has the same breathing room — at 96dp it looked cramped.
        prev = self._native_gift_cell(ctx, g, strip_number=True) or self._gift_preview(ctx, g)
        psz = AndroidUtilities.dp(116)
        lp_prev = LinearLayout.LayoutParams(psz, psz)
        top.addView(prev, lp_prev)

        info = LinearLayout(ctx)
        info.setOrientation(LinearLayout.VERTICAL)
        lp_info = LinearLayout.LayoutParams(0, -2, 1.0)
        lp_info.leftMargin = AndroidUtilities.dp(12)

        gid = int(g.get("unique_id") or 0) or int(g.get("saved_id") or 0)
        is_regular = self._gift_is_regular(g)

        title = TextView(ctx)
        # only NFT collectible number («#134»); regular gifts (num=0) → no «#…»
        num = g.get("num") or 0
        title.setText(str(g.get("title", "Gift")) + (f" #{num}" if num else ""))
        title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 17)
        title.setTextColor(Theme.getColor(Theme.key_dialogTextBlack))
        try:
            title.setTypeface(AndroidUtilities.bold())
        except Exception:
            pass
        # title row: [title | sale chip | TON chip]. The sale chip drives the ВИЗУАЛЬНУЮ
        # «продажу» (звёзды / GRAM), the TON chip — «хранение в блокчейне TON»
        # (both NFT/unique-only; regular gifts have neither row on the native sheet).
        title_row = LinearLayout(ctx)
        title_row.setOrientation(LinearLayout.HORIZONTAL)
        title_row.setGravity(Gravity.CENTER_VERTICAL)
        title_row.addView(title, LinearLayout.LayoutParams(0, -2, 1.0))
        if not is_regular:
            try:
                slp = LinearLayout.LayoutParams(-2, -2)
                slp.leftMargin = AndroidUtilities.dp(6)
                title_row.addView(self._sale_chip(ctx, g, gid), slp)
            except Exception:
                pass
            try:
                tlp = LinearLayout.LayoutParams(-2, -2)
                tlp.leftMargin = AndroidUtilities.dp(6)
                title_row.addView(self._ton_chip(ctx, g, gid), tlp)
            except Exception:
                pass
        info.addView(title_row, LinearLayout.LayoutParams(-1, -2))

        # sub-table: NFT attributes OR editable «От/Дата/Комментарий» rows (regular)
        tbl = LinearLayout(ctx)
        tbl.setOrientation(LinearLayout.VERTICAL)
        tb = GradientDrawable()
        tb.setColor(Theme.getColor(Theme.key_windowBackgroundGray))
        tb.setCornerRadius(AndroidUtilities.dp(10))
        tbl.setBackground(tb)
        tp = AndroidUtilities.dp(8)
        tbl.setPadding(tp, AndroidUtilities.dp(6), tp, AndroidUtilities.dp(6))
        any_attr = False
        if is_regular:
            rows = (("От", "custom_from", "не указано", "От кого (user id)", True),
                    ("Дата", "custom_date", "не указана", "Дата и время (например 23.03.2026 14:30)", False),
                    ("Комментарий", "custom_comment", "не указан", "Комментарий", False))
            for label, field, placeholder, dlg_title, numeric in rows:
                any_attr = True
                cur = str(g.get(field) or "").strip()
                r = self._meta_row(ctx, label, cur if cur else "Добавить", bool(cur),
                                   lambda v, f=field, c=cur, t=dlg_title, nm=numeric, k=gid:
                                       self._edit_regular_field(k, f, c, t, nm))
                rlp = LinearLayout.LayoutParams(-1, -2)
                rlp.topMargin = AndroidUtilities.dp(3)
                tbl.addView(r, rlp)
        else:
            for label, key in (("Model", "model"), ("Symbol", "symbol"), ("Backdrop", "backdrop")):
                val = g.get(key)
                if not val:
                    continue
                any_attr = True
                r = LinearLayout(ctx)
                r.setOrientation(LinearLayout.HORIZONTAL)
                lbl = TextView(ctx)
                lbl.setText(label)
                lbl.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
                lbl.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
                r.addView(lbl, LinearLayout.LayoutParams(0, -2, 1.0))
                vv = TextView(ctx)
                vv.setText(str(val))
                vv.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
                vv.setTextColor(Theme.getColor(Theme.key_dialogTextBlack))
                r.addView(vv, LinearLayout.LayoutParams(-2, -2))
                rlp = LinearLayout.LayoutParams(-1, -2)
                rlp.topMargin = AndroidUtilities.dp(3)
                tbl.addView(r, rlp)
        if any_attr:
            mlp = LinearLayout.LayoutParams(-1, -2)
            mlp.topMargin = AndroidUtilities.dp(8)
            info.addView(tbl, mlp)

        top.addView(info, lp_info)
        card.addView(top, LinearLayout.LayoutParams(-1, -2))

        # One action language for every gift: edit (NFT), persistent Hide/Show, delete.
        actions = LinearLayout(ctx)
        actions.setOrientation(LinearLayout.HORIZONTAL)
        alp = LinearLayout.LayoutParams(-1, -2)
        alp.topMargin = AndroidUtilities.dp(12)

        if not is_regular:
            edit = self._pill(ctx, "Изменить", Theme.getColor(Theme.key_featuredStickers_addButton),
                              lambda v, gg=g: self._open_constructor(gg))
            ep = LinearLayout.LayoutParams(0, AndroidUtilities.dp(44), 1.0)
            ep.rightMargin = AndroidUtilities.dp(8)
            actions.addView(edit, ep)

        hidden = bool(g.get("hidden_override", False))
        visibility = self._pill(ctx, "Показать" if hidden else "Скрыть",
                                Theme.getColor(Theme.key_featuredStickers_addButton),
                                lambda v, k=gid, show=hidden: self._set_gift_visibility(k, show))
        vp = LinearLayout.LayoutParams(0, AndroidUtilities.dp(44), 1.0)
        vp.rightMargin = AndroidUtilities.dp(8)
        actions.addView(visibility, vp)

        gname = str(g.get("title", "Подарок")) + (f" #{num}" if num else "")
        dele = self._pill(ctx, "Удалить", Theme.getColor(Theme.key_text_RedRegular),
                          lambda v, k=gid, nm=gname: self._confirm_delete_gift(k, nm))
        actions.addView(dele, LinearLayout.LayoutParams(0, AndroidUtilities.dp(44), 1.0))

        card.addView(actions, alp)
        return card

    def _set_gift_visibility(self, gift_id, visible):
        result = self._jvoid("setGiftVisibility", ("long", "int"),
                             (int(gift_id), 1 if visible else 0))
        self._gifts_cache = None
        self._toast("Подарок снова виден" if visible else "Подарок скрыт из профиля")
        try:
            self._gifts_all = list(self._gifts() or [])
            search = getattr(self, "_gifts_search", None)
            self._apply_gift_search(str(search.getText() or "") if search is not None else "")
        except Exception:
            pass
        return result

    def _ton_drawable_id(self):
        try:
            return int(getattr(jclass("org.telegram.messenger.R$drawable"), "msg_ton"))
        except Exception:
            return 0

    _TON_BLUE = 0xFF0098EA

    def _ton_chip(self, ctx, g, gid):
        """Pretty TON pill on a gift card → opens «хранение в блокчейне TON» config. Filled
        TON-blue when an address is set, outlined when off."""
        enabled = bool(str(g.get("ton_address") or "").strip())
        chip = LinearLayout(ctx)
        chip.setOrientation(LinearLayout.HORIZONTAL)
        chip.setGravity(Gravity.CENTER_VERTICAL)
        chip.setPadding(AndroidUtilities.dp(9), AndroidUtilities.dp(5), AndroidUtilities.dp(11), AndroidUtilities.dp(5))
        bg = GradientDrawable()
        bg.setCornerRadius(float(AndroidUtilities.dp(14)))
        if enabled:
            bg.setColor(self._col(self._TON_BLUE))
        else:
            bg.setColor(self._col(0x1F0098EA))                       # faint blue fill
            bg.setStroke(AndroidUtilities.dp(1), self._col(0x800098EA))
        chip.setBackground(bg)
        fg = self._col(0xFFFFFFFF) if enabled else self._col(self._TON_BLUE)
        # TON diamond icon (bundled R.drawable.msg_ton)
        try:
            rid = self._ton_drawable_id()
            if rid and ImageView is not None:
                iv = ImageView(ctx)
                iv.setImageResource(rid)
                try: iv.setColorFilter(fg)
                except Exception: pass
                ilp = LinearLayout.LayoutParams(AndroidUtilities.dp(15), AndroidUtilities.dp(15))
                ilp.rightMargin = AndroidUtilities.dp(5)
                chip.addView(iv, ilp)
        except Exception:
            pass
        t = TextView(ctx)
        t.setText("TON")
        t.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
        t.setTextColor(fg)
        try:
            t.setTypeface(AndroidUtilities.bold())
        except Exception:
            pass
        chip.addView(t, LinearLayout.LayoutParams(-2, -2))
        chip.setOnClickListener(self._click(lambda v, k=gid, a=str(g.get("ton_address") or ""): self._open_ton_config(k, a), hap="select"))
        return chip

    def _open_ton_config(self, gid, current):
        """Configure «хранение подарка в блокчейне TON»: set the owner wallet (a ник.ton or a
        raw address). The Java enrich() then stamps owner_address/gift_address so the native
        gift sheet shows «Подарок хранится в блокчейне TON. Посмотреть → / Владелец: <addr>».
        Empty input disables it."""
        cur = str(current or "").strip()
        def _submit(text):
            addr = str(text or "").strip()
            try:
                res = self._jvoid("updateGift", ("long", "str"), (int(gid), json.dumps({"ton_address": addr})))
                self.log("[ton] set gid=%s addr=%r -> %s" % (gid, addr, res))
            except Exception as e:
                self._toast("TON: " + repr(e)[:120]); return
            # re-enrich so owner_address/gift_address get (re)stamped, then refresh the sheet
            try:
                self._jvoid("reloadAll")
            except Exception:
                pass
            self._refresh_gifts_sheet(80)
            self._toast("Подарок хранится в блокчейне TON ✓" if addr else "Хранение в TON отключено")
        self._input("Хранение в блокчейне TON\nник.ton или адрес кошелька (пусто — отключить):",
                    cur, _submit, numeric=False)

    _SALE_GREEN = 0xFF31B545

    def _sale_chip(self, ctx, g, gid):
        """«Продажа» pill on a gift card → visual resale config (звёзды или GRAM/TON).
        Filled green with the current price when listed, outlined when off. The Java
        enrich() stamps gift.resell_amount, so the NATIVE profile grid ribbon and the
        «Продаётся за …» sheet state render themselves. The price also SYNCS: the server
        derives its market index from resale_config, so the listing shows up in the native
        resale market of every other plugin user (KNOWLEDGE §8 «Продажа»)."""
        rc = g.get("resale_config") or {}
        try:
            stars = int(rc.get("stars") or 0)
        except Exception:
            stars = 0
        try:
            nano = int(rc.get("nanoton") or 0)
        except Exception:
            nano = 0
        ton_only = bool(rc.get("ton_only"))
        on_sale = stars > 0 or nano > 0
        chip = LinearLayout(ctx)
        chip.setOrientation(LinearLayout.HORIZONTAL)
        chip.setGravity(Gravity.CENTER_VERTICAL)
        chip.setPadding(AndroidUtilities.dp(9), AndroidUtilities.dp(5), AndroidUtilities.dp(11), AndroidUtilities.dp(5))
        bg = GradientDrawable()
        bg.setCornerRadius(float(AndroidUtilities.dp(14)))
        if on_sale:
            bg.setColor(self._col(self._SALE_GREEN))
        else:
            bg.setColor(self._col(0x1F31B545))                       # faint green fill
            bg.setStroke(AndroidUtilities.dp(1), self._col(0x8031B545))
        chip.setBackground(bg)
        fg = self._col(0xFFFFFFFF) if on_sale else self._col(self._SALE_GREEN)
        t = TextView(ctx)
        if on_sale and ton_only and nano > 0:
            gram = nano / 1e9
            t.setText(("%s GRAM" % (("%.2f" % gram).rstrip("0").rstrip("."))))
        elif on_sale:
            t.setText("⭐ " + "{:,}".format(stars).replace(",", " "))
        else:
            t.setText("Продажа")
        t.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
        t.setTextColor(fg)
        try:
            t.setTypeface(AndroidUtilities.bold())
        except Exception:
            pass
        chip.addView(t, LinearLayout.LayoutParams(-2, -2))
        chip.setOnClickListener(self._click(lambda v, k=gid, r=dict(rc): self._open_sale_config(k, r), hap="coin"))
        return chip

    def _open_sale_config(self, gid, rc):
        """Configure the ВИЗУАЛЬНУЮ продажу: pick the currency (звёзды / GRAM), enter the
        price, or unlist. Persists resale_config on the entry; Java enrich() then builds
        resell_amount (+ resale_ton_only for GRAM), so the profile grid shows the native
        price ribbon and the gift sheet — «Продаётся за …».

        Telegram itself knows nothing about any of this, but OTHER PLUGIN USERS do: the
        price rides in the snapshot, the server indexes it, and the gift appears in their
        native resale market, where they can buy it or offer their own price. Unlisting
        (an empty resale_config) removes it from that market by the same route."""
        stars = 0
        nano = 0
        try:
            stars = int(rc.get("stars") or 0)
            nano = int(rc.get("nanoton") or 0)
        except Exception:
            pass
        on_sale = stars > 0 or nano > 0

        def _apply(patch, msg):
            try:
                res = self._jvoid("updateGift", ("long", "str"), (int(gid), json.dumps({"resale_config": patch})))
                self.log("[sale] gid=%s cfg=%r -> %s" % (gid, patch, res))
            except Exception as e:
                self._toast("Продажа: " + repr(e)[:120]); return
            try:
                self._jvoid("reloadAll")   # re-enrich → resell_amount (re)stamped + grid invalidated
            except Exception:
                pass
            self._refresh_gifts_sheet(80)
            self._toast(msg)

        def _ask_stars():
            def _submit(text):
                try:
                    n = int(str(text or "0").strip().replace(" ", ""))
                except Exception:
                    self._toast("Введите целое число звёзд"); return
                if n <= 0:
                    self._toast("Цена должна быть больше 0"); return
                _apply({"stars": n}, "Выставлено на продажу за ⭐ %s" % "{:,}".format(n).replace(",", " "))
            self._input("Продажа за звёзды\nЦена в ⭐ (мин. 125):",
                        str(stars) if stars > 0 else "", _submit, numeric=True)

        def _ask_gram():
            def _submit(text):
                try:
                    v = float(str(text or "0").strip().replace(",", ".").replace(" ", ""))
                except Exception:
                    self._toast("Введите цену в GRAM, например 12.5"); return
                if v <= 0:
                    self._toast("Цена должна быть больше 0"); return
                _apply({"nanoton": int(round(v * 1e9)), "ton_only": True},
                       "Выставлено на продажу за %s GRAM" % (("%.2f" % v).rstrip("0").rstrip(".")))
            self._input("Продажа за GRAM (TON)\nЦена в GRAM:",
                        (("%.2f" % (nano / 1e9)).rstrip("0").rstrip(".")) if nano > 0 else "",
                        _submit, numeric=False)

        try:
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None or AlertDialogBuilder is None:
                _ask_stars(); return
            b = AlertDialogBuilder(ctx)
            b.set_title("Продажа подарка (визуально)")
            items = ["Продать за звёзды ⭐", "Продать за GRAM 💎"]
            if on_sale:
                items.append("Снять с продажи")

            def _pick(dlg, idx):
                try:
                    dlg.dismiss()
                except Exception:
                    pass
                if idx == 0:
                    _ask_stars()
                elif idx == 1:
                    _ask_gram()
                else:
                    _apply({}, "Подарок снят с продажи")
            b.set_items(items, _pick)
            b.set_negative_button("Отмена", None)
            run_on_ui_thread(b.show)
        except Exception:
            _ask_stars()

    def _meta_row(self, ctx, label, value, has_val, on_click):
        """A tappable «label … value ✎» row for editable regular-gift overrides."""
        r = LinearLayout(ctx)
        r.setOrientation(LinearLayout.HORIZONTAL)
        r.setGravity(Gravity.CENTER_VERTICAL)
        r.setOnClickListener(self._click(on_click))
        try:
            r.setPadding(AndroidUtilities.dp(2), AndroidUtilities.dp(4), AndroidUtilities.dp(2), AndroidUtilities.dp(4))
        except Exception:
            pass
        lbl = TextView(ctx)
        lbl.setText(label)
        lbl.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
        lbl.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
        r.addView(lbl, LinearLayout.LayoutParams(0, -2, 1.0))
        vv = TextView(ctx)
        vv.setText(str(value))
        vv.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
        # filled → normal text; empty («Добавить») → accent colour as a hint
        vv.setTextColor(Theme.getColor(Theme.key_dialogTextBlack if has_val
                                       else Theme.key_featuredStickers_addButton))
        r.addView(vv, LinearLayout.LayoutParams(-2, -2))
        return r

    def _edit_regular_field(self, gid, field, current, dlg_title, numeric):
        def _submit(text):
            self._set_regular_field(gid, field, str(text or ""))
        self._input(dlg_title, current, _submit, numeric=numeric)

    def _regular_field_patch(self, field, value):
        """The entry patch one «От / Дата / Комментарий» override turns into.

        Routed like production: custom_from → identity_config.from_user_id, custom_date →
        custom_date_ts. Shared with the bulk editor, so one selected gift and twenty of them
        are written exactly the same way.
        """
        raw = str(value or "").strip()
        patch = {field: raw}
        if field == "custom_from":
            uid = self._parse_from_uid(raw)
            if uid > 0:
                # a uid → resolve the display name so OTHER viewers (who don't know
                # this user) still see it; fall back to the raw uid string
                name = self._resolve_user_name(uid) or raw
            else:
                # a plain name → synthesize a stable id so from_id can reference the
                # injected fake user that carries the name
                name = raw
                if raw:
                    import hashlib as _hl
                    uid = 7000000000000 + (int(_hl.md5(raw.encode("utf-8")).hexdigest()[:12], 16) % 1000000000)
            patch["identity_config"] = {"from_user_id": int(uid)} if uid > 0 else {}
            patch["custom_from_name"] = name if uid > 0 else ""
        elif field == "custom_date":
            ts = self._parse_date_ts(raw)
            patch["custom_date_ts"] = int(ts)   # 0 clears the override
        return patch

    def _set_regular_field(self, gid, field, value):
        """Persist ONE regular-gift override on ONE gift."""
        try:
            raw = str(value or "").strip()
            patch = self._regular_field_patch(field, raw)
            res = self._jvoid("updateGift", ("long", "str"), (int(gid), json.dumps(patch)))
            try:
                self.log("[gift] updateGift %s=%r -> %s" % (field, raw, res))
            except Exception:
                pass
            # refresh the sheet so the row shows the new value
            self._refresh_gifts_sheet(80)
        except Exception as e:
            self._toast("сохранение: " + repr(e)[:140])

    def _resolve_user_name(self, uid):
        """Display name of a user id from the local cache (for the «От» sender), or ''."""
        try:
            mc = jclass("org.telegram.messenger.MessagesController").getInstance(_selected_account())
            u = mc.getUser(JLong(int(uid)))
            if u is None:
                return ""
            first = str(getattr(u, "first_name", "") or "").strip()
            last = str(getattr(u, "last_name", "") or "").strip()
            return (first + " " + last).strip()
        except Exception:
            return ""

    def _parse_from_uid(self, raw):
        s = str(raw or "").strip()
        if s.startswith("@"):
            s = s[1:]
        try:
            return int(s) if s.isdigit() else 0
        except Exception:
            return 0

    def _parse_date_ts(self, raw):
        s = str(raw or "").strip()
        if not s:
            return 0
        import datetime as _dt
        # date+time first (so "23.03.2026 14:30" keeps the time), then date-only
        for fmt in ("%d.%m.%Y %H:%M:%S", "%d.%m.%Y %H:%M", "%d.%m.%y %H:%M",
                    "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M",
                    "%d/%m/%Y %H:%M", "%d-%m-%Y %H:%M",
                    "%d.%m.%Y", "%d.%m.%y", "%Y-%m-%d", "%d/%m/%Y", "%d/%m/%y", "%d-%m-%Y"):
            try:
                return int(_dt.datetime.strptime(s, fmt).timestamp())
            except Exception:
                continue
        return 0

    # ---- visual UPGRADE: regular gift → roll random attrs → save as NFT ----
    def _entry_upgradable(self, g):
        """True if this is a regular gift that has an upgrade available (upgrade_stars>0
        and not already unique) — i.e. it can be turned into an NFT."""
        try:
            if str(g.get("kind") or g.get("gift_kind") or "") != "regular":
                return False
            gift = self._deserialize_gift(g.get("b64"))
            if gift is None:
                return False
            if "unique" in str(gift.getClass().getSimpleName()).lower():
                return False
            return int(getattr(gift, "upgrade_stars", 0) or 0) > 0
        except Exception:
            return False

    def _upgrade_regular(self, uid, g):
        base_id = 0
        try:
            base_id = int(g.get("base_gift_id") or 0)
        except Exception:
            base_id = 0
        if base_id <= 0:
            try:
                gift = self._deserialize_gift(g.get("b64"))
                base_id = int(getattr(gift, "id", 0) or 0) if gift is not None else 0
            except Exception:
                base_id = 0
        if base_id <= 0:
            self._toast("нет base_gift_id для улучшения")
            return
        title = str(g.get("title") or "NFT") or "NFT"
        self._toast("улучшаю…")

        def _on(models, patterns, backdrops, raw):
            if raw is not None and int(getattr(raw, "size", lambda: 0)()) > 0:
                self._show_upgrade_roll(uid, title, raw, base_id, models, patterns, backdrops)
            elif models or patterns or backdrops:
                self._finalize_upgrade(uid, title, base_id, None, None, None,
                                       None, models, patterns, backdrops)
            else:
                self._toast("Атрибуты улучшения недоступны")
        self._fetch_upgrade_attrs(base_id, _on)

    def _show_upgrade_roll(self, uid, title, attr_list, base_id, models, patterns, backdrops):
        """Open the native StarGiftPreviewSheet (RANDOM/rolling mode) as the upgrade
        animation, let it roll, then land on the previewed random combo + save."""
        try:
            self._install_ctor_hooks()
            frag = get_last_fragment()
            act = frag.getParentActivity() if frag else None
            if act is None:
                self._toast("нет контекста")
                return
            Sheet = jclass("org.telegram.ui.Stars.StarGiftPreviewSheet")
            rp = None
            try:
                rp = frag.getResourceProvider()
            except Exception:
                rp = None
            sheet = Sheet(act, rp, _selected_account(), str(title), attr_list, False)
            self._nat_sheet = sheet
            sheet.show()
            self._kill_sheet_anim(sheet)
            # NOTE: do NOT seed → the sheet stays in RANDOM mode (cycling preview =
            # the «прокрутка» animation). Land + save after the roll.
            run_on_ui_thread(
                lambda: self._finalize_upgrade_from_sheet(sheet, uid, title, base_id,
                                                          models, patterns, backdrops), 2600)
        except Exception as e:
            self._toast("улучшение: " + repr(e)[:140])
            self.log("[upg] roll: " + _cause(e))

    def _finalize_upgrade_from_sheet(self, sheet, uid, title, base_id, models, patterns, backdrops):
        model = pattern = backdrop = None
        try:
            tv = self._jfield(sheet, "topView")
            if tv is not None:
                try: model = tv.getUpgradeImageViewAttribute()
                except Exception: pass
                try: pattern = tv.getUpgradePatternAttribute()
                except Exception: pass
                try: backdrop = tv.getUpgradeBackdropAttribute()
                except Exception: pass
        except Exception:
            pass
        self._finalize_upgrade(uid, title, base_id, model, pattern, backdrop,
                               sheet, models, patterns, backdrops)

    def _finalize_upgrade(self, uid, title, base_id, model, pattern, backdrop,
                          sheet, models, patterns, backdrops):
        import random as _r
        # fall back to a random pick if the sheet didn't expose the landed attr
        if model is None and models:
            model = _r.choice(models)
        if pattern is None and patterns:
            pattern = _r.choice(patterns)
        if backdrop is None and backdrops:
            backdrop = _r.choice(backdrops)
        base_gift = self._find_base_gift(base_id)
        cap = 0
        try:
            cap = int(getattr(base_gift, "availability_total", 0) or 0) if base_gift is not None else 0
        except Exception:
            cap = 0
        if cap <= 0:
            cap = 99999
        num = _r.randint(1, max(1, min(cap, 999999)))
        ok = self._build_and_save(model, pattern, backdrop, title, num,
                                  base_gift_id=base_id, base_gift=base_gift)
        try:
            if sheet is not None:
                sheet.dismiss()
        except Exception:
            pass
        if ok:
            # replace the regular gift with the freshly-minted NFT
            try:
                self._jvoid("removeGift", ("long",), (int(uid),))
            except Exception:
                pass
            # The reel has stopped: the ratchet ends on the one pattern that ramps to a thud.
            self._hap("reveal", throttle=0.0, essential=True)
            self._toast("Улучшено → NFT #%d ✓" % num)
            self._refresh_gifts_sheet(120)
        else:
            self._hap("error", essential=True)

    # ---- NATIVE upgrade: hook StarGiftSheet, replace the bottom button with
    # «Улучшить», drive the real TG reveal animation (topView.rotateAttributes +
    # page switch) on the live sheet, then save the rolled result as an NFT ----
    def _install_gift_sheet_hooks(self):
        if getattr(self, "_gs_hooks_done", False):
            return
        if MethodHook is None or getattr(self, "hook_method", None) is None or _DoUpgradeHook is None:
            return
        self._gs_hooks_done = True
        try:
            Cls = JavaClass.forName("org.telegram.ui.Stars.StarGiftSheet")
        except Exception as e:
            self.log("[upg] no StarGiftSheet: " + _cause(e))
            return
        refs = []
        try:
            for m in Cls.getDeclaredMethods():
                try:
                    name = str(m.getName())
                    m.setAccessible(True)
                    if name == "doUpgrade":
                        refs.append(self.hook_method(m, _DoUpgradeHook(self)))
                    elif name in ("showCraft", "canCraft") and _CraftGateHook is not None:
                        refs.append(self.hook_method(m, _CraftGateHook(self)))
                    elif name == "openCrafting" and _OpenCraftHook is not None:
                        refs.append(self.hook_method(m, _OpenCraftHook(self)))
                    elif name == "set" and _CraftSetHook is not None:
                        refs.append(self.hook_method(m, _CraftSetHook(self)))
                except Exception:
                    continue
        except Exception as e:
            self.log("[upg] gs hook err: " + _cause(e))
        self._gs_hook_refs = refs
        self.log("[gift-sheet] upgrade/craft hooks: " + str(len(refs)))

    def _match_craft_entry(self, sheet):
        """Return the local, not-yet-crafted NFT shown by a native gift sheet."""
        if sheet is None:
            return None
        try:
            gift = None
            try: gift = sheet.getUniqueGift()
            except Exception: pass
            if gift is None:
                saved = self._jfield(sheet, "savedStarGift")
                gift = _gv(saved, "gift", None)
            if gift is None or bool(_gv(gift, "crafted", False)):
                return None
            gid = int(_gv(gift, "id", 0) or 0)
            slug = str(_gv(gift, "slug", "") or "")
            for entry in self._gifts():
                try:
                    kind = str(entry.get("kind") or entry.get("gift_kind") or "")
                    if kind == "regular" or bool(entry.get("crafted")):
                        continue
                    eid = self._gift_display_id(entry)
                    base_id = self._craft_base_id(entry)
                    same = gid > 0 and (eid == gid or base_id == gid)
                    if not same and slug:
                        same = str(entry.get("slug") or "") == slug
                    if same and base_id > 0:
                        return entry
                except Exception:
                    continue
        except Exception:
            pass
        return None

    def _show_native_craft_button(self, sheet):
        """Reveal AyuGram's built-in filled_forge shortcut beside the three dots."""
        entry = self._match_craft_entry(sheet)
        if entry is None or not self._craft_entry_eligible(entry, sheet, resolve=True):
            return False
        try:
            top = self._jfield(sheet, "topView")
            craft_view = self._jfield(top, "craftView") if top is not None else None
            if craft_view is None:
                return False
            craft_view.setVisibility(0)
            craft_view.setAlpha(1.0)
            craft_view.setEnabled(True)
            craft_view.setClickable(True)
            try: craft_view.bringToFront()
            except Exception: pass
            try:
                craft_view.setScaleX(0.86); craft_view.setScaleY(0.86)
                craft_view.animate().scaleX(1.0).scaleY(1.0).alpha(1.0).setDuration(180).start()
            except Exception:
                pass
            return True
        except Exception as e:
            self.log("[craft] show button: " + _cause(e))
            return False

    def _craft_entry_eligible(self, entry, sheet=None, resolve=True):
        """A collection is craftable only when Telegram returns crafted model attrs."""
        base_id = self._craft_base_id(entry)
        resale = entry.get("resale_config") or {}
        try: on_sale = int(resale.get("stars") or 0) > 0 or int(resale.get("nanoton") or 0) > 0
        except Exception: on_sale = False
        if (base_id <= 0 or bool(entry.get("crafted")) or on_sale
                or bool(str(entry.get("ton_address") or "").strip())):
            return False
        cache = getattr(self, "_craft_eligible_cache", None)
        if cache is None:
            cache = self._craft_eligible_cache = {}
        if base_id in cache:
            return bool(cache[base_id])
        if not resolve:
            return False
        pending = getattr(self, "_craft_eligible_pending", None)
        if pending is None:
            pending = self._craft_eligible_pending = set()
        if base_id in pending:
            return False
        pending.add(base_id)
        plugin = self

        def _resolved(models, patterns, backdrops, raw=None):
            eligible = False
            try:
                eligible = (bool(patterns) and bool(backdrops)
                            and any(bool(_gv(m, "crafted", False)) for m in models))
            except Exception:
                eligible = False
            cache[base_id] = bool(eligible)
            pending.discard(base_id)
            if eligible and sheet is not None:
                try:
                    plugin._show_native_craft_button(sheet)
                    if run_on_ui_thread is not None:
                        run_on_ui_thread(lambda: plugin._show_native_craft_button(sheet), 180)
                except Exception: pass
        self._fetch_upgrade_attrs(base_id, _resolved)
        return False

    def _on_do_upgrade(self, sheet):
        """Called from the doUpgrade() hook. If this sheet shows OUR upgradable gift,
        block the real RPC and play the native reveal with a random local NFT.
        Returns True to consume the call, False to let the native upgrade proceed."""
        if sheet is None:
            return False
        if getattr(self, "_upg_busy", False):
            return True   # already upgrading this one — swallow re-taps
        # Find the opened gift wrapper: savedStarGift wrapper has an inner .gift. Try a few field
        # names (a newer TG may rename it). No getClass() here — keep this exception-free so the
        # diagnostic below is ALWAYS reached.
        saved = None
        for _fn in ("savedStarGift", "savedGift", "starGift"):
            try:
                v = self._jfield(sheet, _fn)
            except Exception:
                v = None
            if v is not None and _gv(v, "gift", None) is not None:
                saved = v
                break
        entry = self._match_upgrade_entry(saved)
        if entry is None:
            # ALWAYS surface WHY the fake-upgrade interception missed (temporary diag; the toast
            # tells us: was the wrapper found, the inner gift class/id, and our regular base ids).
            try:
                inner = _gv(saved, "gift", None) if saved is not None else None
                iid = 0
                icls = "NONE"
                if inner is not None:
                    try: iid = int(_gv(inner, "id", 0) or 0)
                    except Exception: iid = -1
                    try: icls = str(inner.getClass().getSimpleName())[:18]
                    except Exception: icls = "?"
                regs = []
                for g in self._gifts():
                    if str(g.get("kind") or g.get("gift_kind") or "") == "regular":
                        try: regs.append(int(g.get("base_gift_id") or 0))
                        except Exception: pass
                self._toast("upg no-match: saved=%s inner=%s id=%d base=%s" % (saved is not None, icls, iid, regs[:4]))
            except Exception as e:
                try: self._toast("upg diag EXC: " + repr(e)[:90])
                except Exception: pass
            return False   # not ours → real gift, let TG upgrade normally
        self._upg_busy = True
        try:
            base_id = int(entry.get("base_gift_id") or 0)
            reg_uid = int(entry.get("unique_id") or 0) or int(entry.get("saved_id") or 0)
            title = str(entry.get("title") or "NFT") or "NFT"
            # the preview pool openUpgrade() already fetched (correct format for the roll)
            sa = self._jfield(sheet, "sample_attributes")
            models, patterns, backdrops = self._split_attrs(sa) if sa is not None else ([], [], [])
            import random as _r
            model = _r.choice(models) if models else None
            pattern = _r.choice(patterns) if patterns else None
            backdrop = _r.choice(backdrops) if backdrops else None
            base_gift = self._find_base_gift(base_id)
            cap = 0
            try:
                cap = int(getattr(base_gift, "availability_total", 0) or 0) if base_gift is not None else 0
            except Exception:
                cap = 0
            num = _r.randint(1, max(1, min(cap if cap > 0 else 99999, 999999)))
            # «С именем отправителя» checked → keep original details (sender/date/comment)
            # as the native bottom row on the upgraded NFT
            keep = False
            try:
                cb = self._jfield(sheet, "checkbox")
                keep = bool(cb.isChecked()) if cb is not None else False
            except Exception:
                keep = False
            od = None
            if keep:
                suid = self._parse_from_uid(str(entry.get("custom_from") or ""))
                dts = self._parse_date_ts(str(entry.get("custom_date") or ""))
                cc = str(entry.get("custom_comment") or "").strip()
                if suid > 0 or dts > 0 or cc:
                    od = {"sender_uid": suid, "recipient_uid": _real_uid(),
                          "date_ts": dts, "comment": cc}
            # Build the unique gift OFF the UI thread: the reflective TL construction +
            # serialization froze the «Улучшить» tap for its full duration on weak
            # devices. The hook returns immediately; the reveal starts as soon as the
            # build lands (tens of ms — imperceptible vs a frozen frame).
            def _bg_build(model=model, pattern=pattern, backdrop=backdrop, od=od, num=num):
                try:
                    gift, saved2, b64, name, slug, new_uid = self._build_unique_gift(
                        model, pattern, backdrop, title, num, base_id, base_gift, original_details=od)
                    if not b64:
                        self._upg_busy = False
                        self._toast_ui("сборка не удалась")
                        return

                    def _reveal():
                        played = self._play_native_reveal(sheet, gift)
                        self.log("[upg] reveal=%s num=%d keep=%s" % (played, num, keep))
                        run_on_ui_thread(
                            lambda: self._finish_native_upgrade(reg_uid, b64, name, slug, num, base_id,
                                                                None, None, new_uid=new_uid), 2700)
                    run_on_ui_thread(_reveal)
                except Exception as e:
                    self._upg_busy = False
                    self.log("[upg] build: " + _cause(e))
            import threading
            threading.Thread(target=_bg_build, name="chimeranft-upg-build", daemon=True).start()
        except Exception as e:
            self._upg_busy = False
            self.log("[upg] do_upgrade: " + _cause(e))
        return True

    def _upg_cache(self):
        """The upgrade-match cache for the CURRENT device account.

        It used to be one plain dict for the whole process. Gift entries are per-account, so after
        a switch account A's cached entries answered account B's lookups — B could consume doUpgrade
        against a gift it does not own. Re-keying on the active slot makes a switch drop the stale
        map instead of serving it.
        """
        slot = _selected_account()
        if getattr(self, "_upg_match_slot", None) != slot:
            self._upg_match_slot = slot
            self._upg_match_cache = {}
        cache = getattr(self, "_upg_match_cache", None)
        if cache is None:
            cache = self._upg_match_cache = {}
        return cache

    def _match_upgrade_entry(self, saved):
        """Return our upgradable regular entry that this opened gift corresponds to."""
        try:
            inner = _gv(saved, "gift", None)
            if inner is None:
                return None
            if "unique" in str(inner.getClass().getSimpleName()).lower():
                return None
            inner_id = int(_gv(inner, "id", 0) or 0)
            if inner_id <= 0:
                return None
            cache = self._upg_cache()
            if inner_id in cache:
                cached = cache[inner_id]
                return cached if cached is not False else None
            for g in self._gifts():
                try:
                    if str(g.get("kind") or g.get("gift_kind") or "") != "regular":
                        continue
                    if int(g.get("base_gift_id") or 0) != inner_id:
                        continue
                    if self._entry_upgradable(g):
                        cache[inner_id] = g
                        return g
                except Exception:
                    continue
            cache[inner_id] = False
        except Exception:
            pass
        return None

    def _play_native_reveal(self, sheet, gift):
        """Replicate StarGiftSheet.applyNewGiftFromUpdates() success path so TG plays
        its OWN upgrade roller animation: rolling=true + savedStarGift.gift→our unique
        + set(saved,list) → roller spins (over the sample_attributes openUpgrade set)
        → switchPage(0). No network — the preview state is already up."""
        try:
            saved = self._jfield(sheet, "savedStarGift")
            if saved is None:
                return "no savedStarGift"
            glist = self._jfield(sheet, "giftsList")
            self._jset(sheet, "rolling", True)
            # swap the gift to our freshly-minted unique + mark it upgraded
            self._jset(saved, "gift", gift)
            try:
                flags = int(_gv(saved, "flags", 0) or 0)
                self._jset(saved, "flags", (flags | 8) & ~2048)
            except Exception:
                pass
            self._jset(saved, "saved_id", 0)
            self._jset(saved, "can_upgrade", False)
            try:
                sheet.set(saved, glist)   # re-render → roller reveal (rolling=true)
            except Exception as e:
                self.log("[upg] set(saved): " + _cause(e))
            self._jset(sheet, "sample_attributes", None)
            self._jset(sheet, "rolling", False)
            try:
                sheet.switchPage(0, True)
            except Exception:
                pass
            return "ok"
        except Exception as e:
            return "err: " + _cause(e)

    def _finish_native_upgrade(self, reg_uid, b64, name, slug, num, base_id, sheet, src=None, new_uid=0):
        try:
            try:
                new_uid = int(new_uid or 0)
            except Exception:
                new_uid = 0
            if new_uid <= 0:
                # fallback only — the upgrade path passes new_uid through, so the freshly
                # built b64 is NOT re-deserialized on the UI thread mid-animation
                try:
                    g2 = self._deserialize_gift(b64)
                    new_uid = int(getattr(g2, "id", 0) or 0)
                except Exception:
                    new_uid = 0
            entry = {"b64": b64, "inject": True, "title": name, "slug": slug,
                     "num": int(num or 1), "unique_id": int(new_uid),
                     "base_gift_id": int(base_id or 0), "gift_kind": "local_upgraded"}
            # carry over От/Дата/Комментарий from the source regular gift so the
            # upgraded NFT keeps the «X отправил(а) Вам этот подарок DD.MM.YY» banner
            if isinstance(src, dict):
                cf = str(src.get("custom_from") or "").strip()
                cd = str(src.get("custom_date") or "").strip()
                cc = str(src.get("custom_comment") or "").strip()
                if cf:
                    entry["custom_from"] = cf
                    uid = self._parse_from_uid(cf)
                    if uid > 0:
                        entry["identity_config"] = {"from_user_id": int(uid)}
                if cd:
                    entry["custom_date"] = cd
                    ts = self._parse_date_ts(cd)
                    if ts > 0:
                        entry["custom_date_ts"] = int(ts)
                if cc:
                    entry["custom_comment"] = cc
            # ONE bridge call: drop the source regular gift + add the NFT in a single
            # atomic write and a single re-inject (the old addGift→removeGift pair did
            # two of each right as the reveal animation settled — the end-of-upgrade hitch)
            self._jvoid("replaceGift", ("long", "str"), (int(reg_uid or 0), json.dumps(entry)))
            self._toast("Улучшено → NFT #%d ✓" % num)
            try:
                if sheet is not None:
                    sheet.dismiss()
            except Exception:
                pass
        except Exception as e:
            self.log("[upg] finish: " + _cause(e))
        finally:
            self._upg_busy = False

    def _deserialize_saved(self, b64):
        """Decode the gift b64 → the full TL_savedStarGift WRAPPER (cached per-b64). BULK
        byte[] conversion — the old per-byte JArr.setByte loop was thousands of JNI calls per
        gift on the UI thread for every render → the «Мои подарки» lag. The wrapper feeds both
        our custom preview AND the native GiftCell.setStarsGift()."""
        try:
            if not b64 or jclass is None:
                return None
            cache = getattr(self, "_gift_saved_cache", None)
            if cache is None:
                cache = {}
                self._gift_saved_cache = cache
            if b64 in cache:
                return cache[b64]
            # the TL classes are looked up once, not per cache miss (a fresh sheet with
            # N never-seen gifts used to do 2·N jclass lookups)
            tl = getattr(self, "_tl_classes", None)
            if tl is None:
                tl = (jclass("org.telegram.tgnet.SerializedData"),
                      jclass("org.telegram.tgnet.tl.TL_stars$TL_savedStarGift"))
                self._tl_classes = tl
            SD = tl[0]
            raw = base64.b64decode(b64)

            def _mk():
                try:
                    return SD(raw)                  # Chaquopy bulk-converts bytes → byte[]
                except Exception:
                    pass
                try:
                    return SD(jarray(jbyte)(raw))   # explicit bulk byte[] (still no per-byte loop)
                except Exception:
                    pass
                # last-resort (slow per-byte) — runs at most once per b64 thanks to the cache
                JByte = jclass("java.lang.Byte").TYPE
                JArr = jclass("java.lang.reflect.Array")
                arr = JArr.newInstance(JByte, len(raw))
                for i, b in enumerate(raw):
                    JArr.setByte(arr, i, b - 256 if b > 127 else b)
                return SD(arr)

            data = _mk()
            Saved = tl[1]
            try:
                ctor = data.readInt32(False)
            except Exception:
                ctor = 0
            obj = None
            try:
                obj = Saved.TLdeserialize(data, ctor, False)
            except Exception:
                obj = None
            if obj is None:
                data = _mk()
                try:
                    data.readInt32(False)
                except Exception:
                    pass
                obj = Saved()
                obj.readParams(data, False)
            if obj is not None:
                # every edit produces a NEW b64 key, so stale wrappers accumulate —
                # bound the cache (dicts are insertion-ordered → drop the oldest)
                while len(cache) >= 256:
                    try:
                        cache.pop(next(iter(cache)))
                    except Exception:
                        cache.clear()
                cache[b64] = obj
            return obj
        except Exception:
            return None

    def _deserialize_gift(self, b64):
        """Inner gift (TL_starGiftUnique) from the cached saved-gift wrapper."""
        obj = self._deserialize_saved(b64)
        if obj is None:
            return None
        try:
            return getattr(obj, "gift", None)
        except Exception:
            return None

    def _argb_signed(self, c):
        v = (0xFF000000 | (int(c) & 0xFFFFFF))
        if v >= 0x80000000:
            v -= 0x100000000
        return int(v)

    def _gift_preview(self, ctx, g):
        wrap = FrameLayout(ctx)
        gd = GradientDrawable()
        gd.setCornerRadius(AndroidUtilities.dp(14))
        gd.setColor(Theme.getColor(Theme.key_windowBackgroundGray))
        wrap.setBackground(gd)

        gift = None
        try:
            gift = self._deserialize_gift(g.get("b64"))
        except Exception:
            gift = None
        if gift is None:
            return wrap

        center = edge = patc = None
        pattern_doc = model_doc = None
        try:
            attrs = getattr(gift, "attributes", None)
            n = int(attrs.size()) if attrs is not None else 0
            for i in range(n):
                a = attrs.get(i)
                if a is None:
                    continue
                cls = str(a.getClass().getSimpleName()).lower()
                if "backdrop" in cls:
                    try: center = self._argb_signed(getattr(a, "center_color", 0) or 0)
                    except Exception: pass
                    try: edge = self._argb_signed(getattr(a, "edge_color", 0) or 0)
                    except Exception: pass
                    try: patc = self._argb_signed(getattr(a, "pattern_color", 0) or 0)
                    except Exception: pass
                elif "model" in cls:
                    model_doc = getattr(a, "document", None)
                elif "pattern" in cls or "symbol" in cls:
                    pattern_doc = getattr(a, "document", None)
        except Exception:
            pass
        if model_doc is None:
            model_doc = getattr(gift, "sticker", None)
        # regular gifts have no backdrop/pattern → render the sticker bigger so it
        # fills the square evenly (matches the look of NFT previews)
        has_backdrop = center is not None and edge is not None

        # 1) backdrop radial gradient
        if center is not None and edge is not None and jarray is not None:
            try:
                grad = GradientDrawable()
                grad.setShape(GradientDrawable.RECTANGLE)
                grad.setCornerRadius(AndroidUtilities.dp(14))
                grad.setGradientType(GradientDrawable.RADIAL_GRADIENT)
                try: grad.setGradientCenter(0.5, 0.5)
                except Exception: pass
                grad.setGradientRadius(AndroidUtilities.dp(64))
                grad.setColors(jarray(jint)([center, edge]))
                wrap.setBackground(grad)
            except Exception:
                pass

        # 2) scattered pattern symbols
        if pattern_doc is not None and BackupImageView is not None and ImageLocation is not None:
            pc = patc if patc is not None else self._argb_signed(0x66FFFFFF)
            positions = (
                (Gravity.LEFT | Gravity.TOP, 4, 4, 14),
                (Gravity.RIGHT | Gravity.TOP, 4, 4, 14),
                (Gravity.LEFT | Gravity.BOTTOM, 4, 4, 14),
                (Gravity.RIGHT | Gravity.BOTTOM, 4, 4, 14),
                (Gravity.CENTER_HORIZONTAL | Gravity.TOP, 0, 2, 12),
                (Gravity.CENTER_HORIZONTAL | Gravity.BOTTOM, 0, 2, 12),
                (Gravity.LEFT | Gravity.CENTER_VERTICAL, 2, 0, 12),
                (Gravity.RIGHT | Gravity.CENTER_VERTICAL, 2, 0, 12),
            )
            for grav, mx, my, sz in positions:
                try:
                    piv = BackupImageView(ctx)
                    loc = ImageLocation.getForDocument(pattern_doc)
                    if loc is None:
                        continue
                    piv.setImage(loc, f"{sz}_{sz}", None, 0, pattern_doc)
                    try: piv.setColorFilter(pc)
                    except Exception: pass
                    try: piv.setAlpha(0.5)
                    except Exception: pass
                    lp = FrameLayout.LayoutParams(AndroidUtilities.dp(sz), AndroidUtilities.dp(sz), grav)
                    lp.leftMargin = lp.rightMargin = AndroidUtilities.dp(mx)
                    lp.topMargin = lp.bottomMargin = AndroidUtilities.dp(my)
                    wrap.addView(piv, lp)
                except Exception:
                    continue

        # 3) centered model sticker
        if model_doc is not None and BackupImageView is not None and ImageLocation is not None:
            try:
                img = BackupImageView(ctx)
                try: img.setRoundRadius(AndroidUtilities.dp(30))
                except Exception: pass
                loc = ImageLocation.getForDocument(model_doc)
                if loc is not None:
                    img.setImage(loc, "64_64", None, 0, model_doc)
                try: img.startAnimation()
                except Exception: pass
                sz = AndroidUtilities.dp(64 if has_backdrop else 84)
                wrap.addView(img, FrameLayout.LayoutParams(sz, sz, Gravity.CENTER))
            except Exception:
                pass
        return wrap

    def _pill(self, ctx, text, color, on_click):
        tv = TextView(ctx)
        tv.setText(text)
        tv.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 14)
        tv.setTextColor(color)
        tv.setGravity(Gravity.CENTER)
        bg = GradientDrawable()
        bg.setCornerRadius(AndroidUtilities.dp(22))
        try:
            base = color & 0xFFFFFF
            bg.setColor(0x22000000 | base)
        except Exception:
            bg.setColor(Theme.getColor(Theme.key_windowBackgroundGray))
        tv.setBackground(self._ripple_bg(bg, color))
        try: tv.setElevation(float(AndroidUtilities.dp(1)))
        except Exception: pass
        tv.setOnClickListener(self._click(on_click))
        return tv

    # ---- Local gift crafting, rendered by Telegram's native CraftTopView ----
    def _craft_entry_id(self, entry):
        try:
            return int(entry.get("unique_id") or entry.get("saved_id") or 0)
        except Exception:
            return 0

    def _craft_base_id(self, entry):
        try:
            base_id = int(entry.get("base_gift_id") or 0)
        except Exception:
            base_id = 0
        if base_id <= 0:
            try:
                gift = self._deserialize_gift(entry.get("b64"))
                base_id = int(getattr(gift, "gift_id", 0)
                              or getattr(gift, "id", 0) or 0)
            except Exception:
                base_id = 0
        return base_id

    def _craft_candidates(self, seed):
        """All locally owned collectibles from the seed's underlying collection."""
        base_id = self._craft_base_id(seed)
        if base_id <= 0:
            return []
        seed_id = self._craft_entry_id(seed)
        rows = []
        seen = set()
        ordered = [seed] + [x for x in self._gifts() if self._craft_entry_id(x) != seed_id]
        for entry in ordered:
            eid = self._craft_entry_id(entry)
            if eid <= 0 or eid in seen or self._craft_base_id(entry) != base_id:
                continue
            resale = entry.get("resale_config") or {}
            try: on_sale = int(resale.get("stars") or 0) > 0 or int(resale.get("nanoton") or 0) > 0
            except Exception: on_sale = False
            if bool(entry.get("crafted")) or str(entry.get("ton_address") or "").strip() or on_sale:
                continue
            gift = self._deserialize_gift(entry.get("b64"))
            if gift is None:
                continue
            try:
                import time as _time
                if bool(_gv(gift, "crafted", False)) or bool(_gv(gift, "burned", False)):
                    continue
                if str(_gv(gift, "gift_address", "") or "").strip():
                    continue
                if int(_gv(gift, "locked_until_date", 0) or 0) > int(_time.time()):
                    continue
            except Exception:
                continue
            chance = self._local_craft_chance(gift)
            self._jset(gift, "craft_chance_permille", chance)
            seen.add(eid)
            rows.append((entry, gift))
        return rows

    def _local_craft_chance(self, gift):
        """Telegram uses permille (250 = 25%, 1000 = 100%), never 10000."""
        try:
            chance = int(_gv(gift, "craft_chance_permille", 0) or 0)
        except Exception:
            chance = 0
        # Preserve a real server-provided chance. Locally constructed gifts have
        # no server value, so use Telegram's common 25% ingredient contribution.
        if 1 <= chance <= 1000:
            return chance
        return 250

    def _craft_selected_ids(self, craft_view):
        out = set()
        try:
            slots = self._jfield(craft_view, "gifts")
            for i in range(len(slots)):
                try:
                    gift = slots[i].getGift()
                    gid = int(getattr(gift, "id", 0) or 0) if gift is not None else 0
                    if gid > 0:
                        out.add(gid)
                except Exception:
                    pass
        except Exception:
            pass
        return out

    def _open_local_craft_picker(self, callback, candidates, craft_view):
        """Open a local-only ingredient picker without starting Telegram loaders."""
        try:
            selected = self._craft_selected_ids(craft_view)
            live_ids = set(self._craft_entry_id(e) for e in self._gifts())
            available = [(e, g) for e, g in candidates
                         if self._craft_entry_id(e) in live_ids and self._craft_entry_id(e) not in selected]
            if not available:
                self._toast("Все подходящие подарки уже выбраны")
                return
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None:
                return
            scroll = ScrollView(ctx)
            col = LinearLayout(ctx)
            col.setOrientation(LinearLayout.VERTICAL)
            pad = AndroidUtilities.dp(14)
            col.setPadding(pad, pad, pad, AndroidUtilities.dp(24))

            heading = TextView(ctx)
            heading.setText("Выберите подарок для крафта")
            heading.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 20)
            heading.setTextColor(Theme.getColor(Theme.key_dialogTextBlack))
            try: heading.setTypeface(AndroidUtilities.bold())
            except Exception: pass
            col.addView(heading, LinearLayout.LayoutParams(-1, -2))

            subtitle = TextView(ctx)
            subtitle.setText("Доступно: %d · локальный список" % len(available))
            subtitle.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
            subtitle.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
            slp = LinearLayout.LayoutParams(-1, -2)
            slp.topMargin = AndroidUtilities.dp(3)
            slp.bottomMargin = AndroidUtilities.dp(10)
            col.addView(subtitle, slp)

            builder = BottomSheet.Builder(ctx)
            picker_ref = [None]
            click_refs = []
            plugin = self

            def _choose(entry, gift):
                try:
                    eid = plugin._craft_entry_id(entry)
                    current = set(plugin._craft_entry_id(x) for x in plugin._gifts())
                    if eid not in current:
                        plugin._toast("Подарок уже недоступен")
                        return
                    callback.run(gift)
                    if picker_ref[0] is not None:
                        picker_ref[0].dismiss()
                except Exception as e:
                    plugin.log("[craft] local select: " + _cause(e))
                    plugin._toast("Не удалось выбрать подарок")

            for entry, gift in available:
                row = LinearLayout(ctx)
                row.setOrientation(LinearLayout.HORIZONTAL)
                row.setGravity(Gravity.CENTER_VERTICAL)
                row.setPadding(AndroidUtilities.dp(8), AndroidUtilities.dp(8),
                               AndroidUtilities.dp(10), AndroidUtilities.dp(8))
                bg = GradientDrawable()
                bg.setCornerRadius(float(AndroidUtilities.dp(14)))
                bg.setColor(Theme.getColor(Theme.key_windowBackgroundGray))
                row.setBackground(self._ripple_bg(
                    bg, Theme.getColor(Theme.key_featuredStickers_addButton)))

                preview = self._gift_preview(ctx, entry)
                row.addView(preview, LinearLayout.LayoutParams(
                    AndroidUtilities.dp(58), AndroidUtilities.dp(58)))

                texts = LinearLayout(ctx)
                texts.setOrientation(LinearLayout.VERTICAL)
                title = TextView(ctx)
                name = str(entry.get("title") or _gv(gift, "title", None) or "Подарок")
                try: num = int(entry.get("num") or _gv(gift, "num", 0) or 0)
                except Exception: num = 0
                title.setText(name + ((" #%d" % num) if num > 0 else ""))
                title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 15)
                title.setTextColor(Theme.getColor(Theme.key_dialogTextBlack))
                try: title.setTypeface(AndroidUtilities.bold())
                except Exception: pass
                texts.addView(title, LinearLayout.LayoutParams(-1, -2))
                chance = TextView(ctx)
                chance.setText("Шанс ингредиента: %d%%" %
                               (self._local_craft_chance(gift) // 10))
                chance.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
                chance.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
                texts.addView(chance, LinearLayout.LayoutParams(-1, -2))
                tlp = LinearLayout.LayoutParams(0, -2, 1.0)
                tlp.leftMargin = AndroidUtilities.dp(12)
                row.addView(texts, tlp)

                listener = self._click(lambda v, e=entry, g=gift: _choose(e, g))
                click_refs.append(listener)
                row.setOnClickListener(listener)
                rlp = LinearLayout.LayoutParams(-1, -2)
                rlp.topMargin = AndroidUtilities.dp(7)
                col.addView(row, rlp)

            scroll.addView(col)
            builder.setCustomView(scroll)
            picker = builder.create()
            picker_ref[0] = picker
            self._craft_refs.extend([picker, picker_ref, click_refs, available])
            self._show_sheet_animated(picker, scroll)
        except Exception as e:
            self.log("[craft] picker: " + _cause(e))
            self._toast("Не удалось открыть выбор подарков")

    def _open_local_crafting(self, seed, origin_sheet=None):
        try:
            self._close_gift_detail(animated=True)
            if not self._craft_entry_eligible(seed, origin_sheet, resolve=False):
                self._toast("Эта коллекция не поддерживает крафт")
                return
            candidates = self._craft_candidates(seed)
            if not candidates:
                self._toast("Для этого подарка крафт недоступен")
                return
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None:
                self._toast("Нет контекста для крафта")
                return
            rp = None
            try: rp = frag.getResourceProvider()
            except Exception: pass
            CraftTopView = jclass("org.telegram.ui.Stars.StarGiftSheet$CraftTopView")
            craft = CraftTopView(ctx, rp)
            base_id = self._craft_base_id(seed)
            first_gift = candidates[0][1]
            document = None
            try: document = first_gift.getDocument()
            except Exception: pass
            if document is None:
                try: document = getattr(first_gift, "document", None) or getattr(first_gift, "sticker", None)
                except Exception: pass
            title = str(seed.get("title") or getattr(first_gift, "title", "NFT") or "NFT")
            craft.setup(_selected_account(), int(base_id), document, title)
            self._jset(first_gift, "craft_chance_permille", self._local_craft_chance(first_gift))
            craft.selectGift(first_gift)

            sheet = BottomSheet(ctx, False, rp)
            sheet.setCustomView(craft)
            try: sheet.setCanDismissWithSwipe(False)
            except Exception: pass
            plugin = self
            Callback3 = jclass("org.telegram.messenger.Utilities$Callback3")
            Callback2 = jclass("org.telegram.messenger.Utilities$Callback2")
            Runnable = jclass("java.lang.Runnable")

            class _OnCraft(dynamic_proxy(Callback3)):
                def run(self2, selected, success, failure):
                    plugin._perform_local_craft(base_id, candidates, selected, success, failure, sheet, origin_sheet)

            class _OnAdd(dynamic_proxy(Callback2)):
                def run(self2, callback, will_be_first):
                    plugin._open_local_craft_picker(callback, candidates, craft)

            class _OnClose(dynamic_proxy(Runnable)):
                def run(self2):
                    try: sheet.dismiss()
                    except Exception: pass

            on_craft, on_add, on_close = _OnCraft(), _OnAdd(), _OnClose()
            craft.setOnCraft(on_craft)
            craft.setOnAddGift(on_add)
            craft.setOnClose(on_close)
            self._craft_sheet = sheet
            self._craft_view = craft
            self._craft_refs = [candidates, on_craft, on_add, on_close]
            sheet.show()
        except Exception as e:
            self._toast("Крафт: " + repr(e)[:140])
            self.log("[craft] open: " + _cause(e))

    def _perform_local_craft(self, base_id, candidates, selected, success_cb, failure_cb, sheet, origin_sheet=None):
        """Build first, then atomically burn 1..4 inputs and insert the result."""
        try:
            by_id = {self._craft_entry_id(e): (e, g) for e, g in candidates}
            picked = []
            used = set()
            n = int(selected.size()) if selected is not None else 0
            for i in range(min(n, 4)):
                gift = selected.get(i)
                gid = int(getattr(gift, "id", 0) or 0)
                if gid in by_id and gid not in used:
                    used.add(gid)
                    picked.append((gid, by_id[gid][0], gift))
            if not picked:
                raise ValueError("не выбраны подарки")
            ingredient_ids = [x[0] for x in picked]
            first_id = ingredient_ids[0]
            plugin = self

            # Telegram sums craft_chance_permille from all selected gifts. 1000
            # permille is 100%; a failed attempt burns every selected ingredient.
            import random as _craft_random
            total_chance = min(1000, sum(self._local_craft_chance(x[2]) for x in picked))
            if _craft_random.randrange(1000) >= total_chance:
                result = self._jvoid("removeGifts", ("str",), (json.dumps(ingredient_ids),))
                if result is None or "FAIL" in str(result):
                    raise ValueError(str(result or "ошибка списания подарков"))
                # A null result is Telegram's native unsuccessful-craft path:
                # the cube animation finishes on the failure state.
                success_cb.run(None, None)
                if origin_sheet is None:
                    self._refresh_gifts_sheet(delay=5200)
                return

            def _attrs(models, patterns, backdrops, raw=None):
                try:
                    import random as _random
                    crafted_models = [m for m in models if bool(getattr(m, "crafted", False))]
                    if not crafted_models or not patterns or not backdrops:
                        raise ValueError("атрибуты крафта недоступны")
                    model = _random.choice(crafted_models)
                    pattern = _random.choice(list(patterns))
                    backdrop = _random.choice(list(backdrops))
                    try: plugin._jset(model, "crafted", True)
                    except Exception: pass
                    base_gift = plugin._find_base_gift(base_id)
                    title = str(picked[0][1].get("title") or getattr(picked[0][2], "title", "NFT") or "NFT")
                    num = _random.randint(1, 999999)
                    gift, saved, b64, name, slug, uid = plugin._build_unique_gift(
                        model, pattern, backdrop, title, num, base_id, base_gift,
                        forced_uid=first_id, crafted=True)
                    if not b64 or gift is None:
                        raise ValueError("не удалось собрать результат")
                    import time as _time
                    entry = {"b64": b64, "inject": True, "title": name, "slug": slug,
                             "num": int(num), "unique_id": int(first_id), "saved_id": int(first_id),
                             "base_gift_id": int(base_id), "gift_kind": "local_crafted",
                             "crafted": True, "created_at": int(_time.time())}
                    result = plugin._jvoid("craftGifts", ("str", "str"),
                                           (json.dumps(ingredient_ids), json.dumps(entry)))
                    if result is None or "FAIL" in str(result) or "not found" in str(result):
                        raise ValueError(str(result or "ошибка сохранения"))

                    class _OpenResult(dynamic_proxy(jclass("java.lang.Runnable"))):
                        def run(self2):
                            try: sheet.dismiss()
                            except Exception: pass
                            if origin_sheet is not None:
                                try: origin_sheet.dismiss()
                                except Exception: pass
                                plugin._open_my_gifts()
                            else:
                                plugin._refresh_gifts_sheet(delay=120)
                            plugin._toast("Крафт завершён ✓")
                    open_result = _OpenResult()
                    plugin._craft_refs.append(open_result)
                    success_cb.run(gift, open_result)
                    # The native reveal runs for several seconds; refresh the inventory
                    # underneath it without closing or interrupting the animation.
                    if origin_sheet is None:
                        plugin._refresh_gifts_sheet(delay=5200)
                except Exception as e:
                    plugin.log("[craft] finish: " + _cause(e))
                    try: failure_cb.run()
                    except Exception: pass
                    plugin._toast("Крафт не выполнен: " + str(e)[:100])

            self._fetch_upgrade_attrs(base_id, _attrs)
        except Exception as e:
            self.log("[craft] start: " + _cause(e))
            try: failure_cb.run()
            except Exception: pass
            self._toast("Крафт: " + str(e)[:100])

    def _on_add_gift(self):
        # let the user pick which catalog to open
        try:
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None or AlertDialogBuilder is None:
                self._open_catalog(True)
                return
            b = AlertDialogBuilder(ctx)
            b.set_title("Добавить подарок")
            items = ["NFT подарок (конструктор)", "Обычный подарок"]

            def _pick(dlg, idx):
                try: dlg.dismiss()
                except Exception: pass
                self._open_catalog(idx == 0)
            b.set_items(items, _pick)
            b.set_negative_button("Отмена", None)
            run_on_ui_thread(b.show)
        except Exception:
            self._open_catalog(True)

    # ---- Каталог NFT (114 базовых подарков из StarsController) ----
    def _stars_ctrl(self):
        try:
            acc = _selected_account()
            return jclass("org.telegram.ui.Stars.StarsController").getInstance(acc)
        except Exception:
            return None

    def _catalog_list(self):
        try:
            ctrl = self._stars_ctrl()
            if ctrl is None:
                return []
            for f in ctrl.getClass().getDeclaredFields():
                try:
                    f.setAccessible(True)
                    val = f.get(ctrl)
                except Exception:
                    continue
                if val is None:
                    continue
                try:
                    if "ArrayList" not in str(val.getClass().getName()):
                        continue
                    n = int(val.size())
                    if n <= 0:
                        continue
                    first = val.get(0)
                    fn = str(first.getClass().getName()).lower()
                    if "stargift" in fn and "saved" not in fn:
                        return [val.get(i) for i in range(n)]
                except Exception:
                    continue
        except Exception:
            pass
        return []

    def _is_upgradable(self, g):
        """NFT-able gift: has available upgrades (upgrade_stars > 0) or is already unique."""
        try:
            upg = int(getattr(g, "upgrade_stars", 0) or 0)
            if upg > 0:
                return True
        except Exception:
            pass
        try:
            if "unique" in str(g.getClass().getName()).lower():
                return True
        except Exception:
            pass
        return False

    def _catalog_items(self, nft_only):
        """Regular catalog = every gift; NFT catalog = only upgradable ones.
        Both are sorted by FLOOR (min-resale) price DESC so the priciest sit on top
        — owner wants «вверху самые дорогие по флору» (not by the base buy price)."""
        gifts = self._catalog_list()
        out = gifts if not nft_only else [g for g in gifts if self._is_upgradable(g)]
        try:
            out = sorted(out, key=lambda g: -int(self._get_gift_floor_stars(g) or 0))
        except Exception:
            try:
                out = sorted(out, key=lambda g: -int(_gv(g, "stars", 0) or 0))
            except Exception:
                pass
        return out

    def _to_int(self, v, default=0):
        try:
            if v is None:
                return default
            return int(v)
        except Exception:
            try:
                return int(float(str(v)))
            except Exception:
                return default

    def _get_gift_floor_stars(self, gift):
        """Resolve the current floor / min-resale price (in stars) for a catalog gift,
        for the priciest-first sort. Mirrors the legacy runtime gift-floor logic."""
        if gift is None:
            return 0
        for name in ("resell_min_stars", "min_resell_stars", "floor_stars",
                     "floor_price_stars", "min_floor_stars", "min_resale_stars",
                     "resellMinStars", "floorStars", "floorPriceStars"):
            n = self._to_int(_gv(gift, name, None), 0)
            if n > 0:
                return n
        # scan numeric fields whose name smells like a floor / resell-min price
        try:
            for f in gift.getClass().getFields():
                try:
                    tn = f.getType().getName()
                    if tn not in ("int", "long"):
                        continue
                    nm = f.getName().lower()
                    if ("floor" not in nm) and ("resell" not in nm):
                        continue
                    if ("min" not in nm) and ("floor" not in nm):
                        continue
                    try:
                        val = f.getLong(gift) if tn == "long" else f.getInt(gift)
                    except Exception:
                        val = self._to_int(f.get(gift), 0)
                    if int(val) > 0:
                        return int(val)
                except Exception:
                    continue
        except Exception:
            pass
        # ask StarsController for a floor (cached per gift id)
        try:
            gid = self._to_int(_gv(gift, "id", 0), 0)
            if gid > 0:
                cache = getattr(self, "_market_floor_cache", None)
                if cache is None:
                    cache = {}
                    self._market_floor_cache = cache
                cached = cache.get(gid)
                if cached and int(cached) > 0:
                    return int(cached)
                floor2 = self._get_floor_from_stars_controller(gid)
                if floor2 > 0:
                    cache[gid] = int(floor2)
                    return int(floor2)
        except Exception:
            pass
        # last resort: the base buy price, so the sort is at least stable
        return self._to_int(_gv(gift, "stars", 0), 0)

    def _get_floor_from_stars_controller(self, gift_id):
        """Best-effort: call a StarsController method that returns floor/min-resale
        stars for a gift id (method name resolved once by reflection + cached)."""
        gid = self._to_int(gift_id, 0)
        if gid <= 0:
            return 0
        ctrl = self._stars_ctrl()
        if ctrl is None:
            return 0
        if not getattr(self, "_market_floor_method_checked", False):
            self._market_floor_method_checked = True
            best, best_score = None, -1
            try:
                for m in ctrl.getClass().getDeclaredMethods():
                    try:
                        if m.getReturnType().getName() not in ("int", "long"):
                            continue
                        params = m.getParameterTypes()
                        if len(params) != 1:
                            continue
                        if params[0].getName() not in ("int", "long",
                                                       "java.lang.Integer", "java.lang.Long"):
                            continue
                        nm = m.getName().lower()
                        if ("floor" not in nm) and ("resell" not in nm) and ("resale" not in nm):
                            continue
                        score = 0
                        if "floor" in nm:
                            score += 3
                        if "resell" in nm or "resale" in nm:
                            score += 2
                        if "min" in nm:
                            score += 2
                        if "stars" in nm:
                            score += 1
                        if score > best_score:
                            best_score, best = score, m
                    except Exception:
                        continue
            except Exception:
                best = None
            if best is not None:
                try:
                    best.setAccessible(True)
                except Exception:
                    pass
                try:
                    self.log("[cat] floor method: " + best.getName())
                except Exception:
                    pass
            self._market_floor_method = best
        m = getattr(self, "_market_floor_method", None)
        if m is None:
            return 0
        try:
            p0 = m.getParameterTypes()[0].getName()
            if p0 in ("long", "java.lang.Long"):
                res = m.invoke(ctrl, JLong(gid))
            else:
                res = m.invoke(ctrl, JInteger(gid))
            return self._to_int(res, 0)
        except Exception:
            return 0

    def _unsell(self, g):
        """Hide the «продан»/sold-out ribbon on a catalog cell (data-driven)."""
        try:
            self._jset(g, "sold_out", False)
        except Exception:
            pass
        try:
            total = int(getattr(g, "availability_total", 0) or 0)
        except Exception:
            total = 0
        try:
            remains = int(getattr(g, "availability_remains", 0) or 0)
        except Exception:
            remains = 0
        if remains <= 0:
            self._jset(g, "availability_remains", total if total > 0 else 1)

    def _star_balance(self):
        try:
            ctrl = self._stars_ctrl()
            bal = getattr(ctrl, "balance", None)
            if bal is None:
                return ""
            amt = getattr(bal, "amount", None)
            if amt is None:
                amt = bal
            return str(int(amt))
        except Exception:
            return ""

    def _market_cart_fragment_matches(self, fragment):
        current = getattr(self, "_market_cart_fragment", None)
        try:
            return current is not None and current.equals(fragment)
        except Exception:
            return current is fragment

    def _schedule_native_market_cart(self, fragment, initial_root=None, authoritative=False):
        """Install now and retry after Telegram finishes/rebuilds the fragment view."""
        if fragment is None:
            return
        target = getattr(self, "_market_cart_target_fragment", None)
        same_target = False
        try:
            same_target = target is not None and target.equals(fragment)
        except Exception:
            same_target = target is fragment
        if target is not None and not same_target and not authoritative:
            return
        if target is None or not same_target:
            self._market_cart_generation = int(getattr(self, "_market_cart_generation", 0) or 0) + 1
            self._market_cart_target_fragment = fragment
        generation = int(getattr(self, "_market_cart_generation", 0) or 0)
        plugin = self

        def _attempt(root=None):
            try:
                if generation != int(getattr(plugin, "_market_cart_generation", 0) or 0):
                    return
                active = getattr(plugin, "_market_cart_target_fragment", None)
                try:
                    if active is None or not active.equals(fragment):
                        return
                except Exception:
                    if active is not fragment:
                        return
                live_root = root
                if live_root is None:
                    try:
                        live_root = fragment.getFragmentView()
                    except Exception:
                        live_root = _gv(fragment, "fragmentView", None)
                if live_root is not None:
                    plugin._inject_native_market_cart(fragment, live_root)
            except Exception:
                pass

        _attempt(initial_root)
        if run_on_ui_thread is not None:
            # Extra + longer retries: on a per-gift resale page the fragment view is sometimes
            # rebuilt late, so the button was missing («корзины нету … когда заходишь на подарок»).
            # Each attempt is a no-op once the button is present (dedup guard), so extra tries are safe.
            for delay in (100, 280, 650, 1200, 2200, 3500):
                try:
                    run_on_ui_thread(lambda: _attempt(None), delay)
                except Exception:
                    pass

    def _detach_native_market_cart(self, fragment):
        target = getattr(self, "_market_cart_target_fragment", None)
        try:
            target_match = target is not None and target.equals(fragment)
        except Exception:
            target_match = target is fragment
        if target_match:
            self._market_cart_generation = int(getattr(self, "_market_cart_generation", 0) or 0) + 1
            self._market_cart_target_fragment = None

        current = getattr(self, "_market_cart_fragment", None)
        try:
            current_match = current is not None and current.equals(fragment)
        except Exception:
            current_match = current is fragment
        if not current_match:
            return
        button = getattr(self, "_market_cart_button", None)
        try:
            parent = button.getParent() if button is not None else None
            if parent is not None:
                parent.removeView(button)
        except Exception:
            pass
        self._market_cart_fragment = None
        self._market_cart_button = None
        self._market_cart_mode = False
        self._market_cart = []

    def _inject_native_market_cart(self, fragment, root):
        if root is None or fragment is None:
            return
        # A retry may carry the createView result while Telegram has already swapped the
        # fragment root. Always prefer the live container.
        try:
            live_root = fragment.getFragmentView()
            if live_root is not None:
                root = live_root
        except Exception:
            pass
        try:
            old = getattr(self, "_market_cart_fragment", None)
            if old is not None and old.equals(fragment):
                existing = getattr(self, "_market_cart_button", None)
                try:
                    parent = existing.getParent() if existing is not None else None
                    if existing is not None and parent is not None and parent.equals(root):
                        existing.setVisibility(0)
                        existing.setAlpha(1.0)
                        try:
                            existing.setElevation(float(AndroidUtilities.dp(8)))
                        except Exception:
                            pass
                        existing.bringToFront()
                        return
                    if existing is not None and parent is not None:
                        parent.removeView(existing)
                except Exception:
                    pass
            elif old is not None:
                # A new gift page became active before the previous page's destroy callback.
                # Detach the old overlay immediately so only the current Resale root owns one.
                existing = getattr(self, "_market_cart_button", None)
                try:
                    parent = existing.getParent() if existing is not None else None
                    if parent is not None:
                        parent.removeView(existing)
                except Exception:
                    pass
        except Exception:
            pass
        try:
            ctx = root.getContext()
            button = self._tg_icon_button(
                ctx, ("msg_delete",), Theme.getColor(Theme.key_windowBackgroundWhiteBlackText),
                "Корзина подарков", lambda v: self._native_market_cart_action(fragment))
            bg = GradientDrawable()
            bg.setShape(GradientDrawable.OVAL)
            bg.setColor(Theme.getColor(Theme.key_windowBackgroundWhite))
            try:
                button.setElevation(float(AndroidUtilities.dp(6)))
            except Exception:
                pass
            button.setBackground(self._ripple_bg(bg, Theme.getColor(Theme.key_featuredStickers_addButton)))
            button.setPadding(AndroidUtilities.dp(15), AndroidUtilities.dp(15),
                              AndroidUtilities.dp(15), AndroidUtilities.dp(15))
            try:
                LongClick = jclass("android.view.View$OnLongClickListener")
                plugin = self
                class _CartLongClick(dynamic_proxy(LongClick)):
                    def onLongClick(self2, _view):
                        # Invoked by View.performLongClick: an unhandled Python exception crosses
                        # the Chaquopy boundary as a Java throwable and unwinds into the framework's
                        # dispatch, taking the app down on a long press.
                        try:
                            plugin._haptic(_view, plugin._HAPTIC_LONG_PRESS)
                            plugin._activate_native_market_cart(fragment)
                        except Exception as e:
                            plugin.log("[market-cart] long click: " + _cause(e))
                        return True
                listener = _CartLongClick()
                self._market_cart_long_listener = listener
                button.setOnLongClickListener(listener)
            except Exception as e:
                self.log("[market-cart] long press: " + _cause(e))
            lp = FrameLayout.LayoutParams(AndroidUtilities.dp(58), AndroidUtilities.dp(58),
                                          Gravity.BOTTOM | Gravity.RIGHT)
            lp.rightMargin = AndroidUtilities.dp(18)
            lp.bottomMargin = AndroidUtilities.dp(24)
            root.addView(button, lp)
            button.setScaleX(0.72); button.setScaleY(0.72); button.setAlpha(0.0)
            button.animate().alpha(1.0).scaleX(1.0).scaleY(1.0).setDuration(240).start()
            self._market_cart_fragment = fragment
            self._market_cart_button = button
            if old is None or not old.equals(fragment):
                self._market_cart = []
                self._market_cart_mode = False
        except Exception as e:
            self.log("[market-cart] inject: " + _cause(e))

    def _native_market_cart_action(self, fragment):
        cart = list(getattr(self, "_market_cart", []) or [])
        if not bool(getattr(self, "_market_cart_mode", False)):
            self._toast("Зажми корзину, чтобы выбирать подарки")
            return
        if not cart:
            self._market_cart_mode = False
            try:
                self._market_cart_button.animate().rotation(0.0).scaleX(1.0).scaleY(1.0).setDuration(160).start()
            except Exception:
                pass
            return
        self._show_native_market_cart(fragment)

    def _activate_native_market_cart(self, fragment):
        self._market_cart_mode = True
        try:
            self._market_cart_button.animate().rotation(10.0).scaleX(1.10).scaleY(1.10).setDuration(170).start()
        except Exception:
            pass
        self._refresh_native_market_cart(fragment)
        self._toast("Режим корзины включён")

    def _refresh_native_market_cart(self, fragment):
        try:
            list_view = _gv(fragment, "listView", None)
            adapter = _gv(list_view, "adapter", None) if list_view is not None else None
            if adapter is not None:
                adapter.update(True)
        except Exception:
            pass

    def _mark_native_market_cart_items(self, items):
        selected = set(row[0] for row in list(getattr(self, "_market_cart", []) or []))
        try:
            count = int(items.size())
        except Exception:
            try: count = len(items)
            except Exception: count = 0
        for i in range(count):
            try:
                item = items.get(i) if hasattr(items, "get") else items[i]
                gift = _gv(item, "object", None)
                slug = str(_gv(gift, "slug", "") or "")
                if not slug:
                    continue
                item.collapsed = True
                item.checked = slug in selected
            except Exception:
                continue

    def _toggle_native_market_cart(self, fragment, uitem, view=None):
        gift = _gv(uitem, "object", None)
        if gift is None:
            return
        slug = str(_gv(gift, "slug", "") or "")
        cart = list(getattr(self, "_market_cart", []) or [])
        index = next((i for i, row in enumerate(cart) if row[0] == slug), -1)
        if index >= 0:
            cart.pop(index)
            self._toast("Удалено из корзины")
        else:
            title = str(_gv(gift, "title", "") or "NFT")
            cart.append((slug, gift, title))
            self._toast("Добавлено · %d" % len(cart))
        self._market_cart = cart
        selected = index < 0
        try:
            if view is not None:
                view.setChecked(selected, True)
        except Exception:
            pass
        self._refresh_native_market_cart(fragment)
        try:
            b = self._market_cart_button
            b.animate().scaleX(1.16).scaleY(1.16).setDuration(80).start()
            run_on_ui_thread(lambda: b.animate().scaleX(1.0).scaleY(1.0).setDuration(130).start(), 90)
        except Exception:
            pass

    def _show_native_market_cart(self, fragment):
        try:
            ctx = fragment.getParentActivity()
            root = LinearLayout(ctx)
            root.setOrientation(LinearLayout.VERTICAL)
            pad = AndroidUtilities.dp(18)
            root.setPadding(pad, pad, pad, AndroidUtilities.dp(12))

            header = LinearLayout(ctx)
            header.setOrientation(LinearLayout.HORIZONTAL)
            header.setGravity(Gravity.CENTER_VERTICAL)
            cart_icon = ImageView(ctx)
            self._set_tg_icon(cart_icon, ("msg_delete",),
                              Theme.getColor(Theme.key_dialogTextBlack), "Корзина")
            header.addView(cart_icon, LinearLayout.LayoutParams(
                AndroidUtilities.dp(30), AndroidUtilities.dp(30)))
            heading = TextView(ctx)
            heading.setText("Корзина · %d" % len(self._market_cart))
            heading.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 21)
            heading.setTextColor(Theme.getColor(Theme.key_dialogTextBlack))
            try: heading.setTypeface(AndroidUtilities.bold())
            except Exception: pass
            htlp = LinearLayout.LayoutParams(0, -2, 1.0)
            htlp.leftMargin = AndroidUtilities.dp(10)
            header.addView(heading, htlp)
            root.addView(header, LinearLayout.LayoutParams(-1, -2))

            subtitle = TextView(ctx)
            subtitle.setText("Нажми на плитку, чтобы убрать подарок")
            subtitle.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 14)
            subtitle.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
            slp = LinearLayout.LayoutParams(-1, -2)
            slp.topMargin = AndroidUtilities.dp(3)
            slp.bottomMargin = AndroidUtilities.dp(10)
            root.addView(subtitle, slp)
            sheet_ref = [None]

            def _remove(slug):
                self._market_cart = [r for r in self._market_cart if r[0] != slug]
                try: sheet_ref[0].dismiss()
                except Exception: pass
                if self._market_cart:
                    run_on_ui_thread(lambda: self._show_native_market_cart(fragment), 100)

            scroll = ScrollView(ctx)
            grid = LinearLayout(ctx)
            grid.setOrientation(LinearLayout.VERTICAL)
            cart_rows = list(self._market_cart)
            GiftCell = jclass("org.telegram.ui.Gifts.GiftSheet$GiftCell")
            rp = None
            try: rp = fragment.getResourceProvider()
            except Exception: pass
            for start in range(0, len(cart_rows), 3):
                line = LinearLayout(ctx)
                line.setOrientation(LinearLayout.HORIZONTAL)
                for slug, gift, title in cart_rows[start:start + 3]:
                    card = GiftCell(ctx, _selected_account(), rp)
                    card.setStarsGift(gift, False, False, False, False, False)
                    # Gifting from the cart is free (visual) — the native cell would otherwise
                    # render a «⭐ 0» price chip on every tile. Hide the price layout entirely.
                    try:
                        card.hidePrice()
                    except Exception:
                        pass
                    card.setChecked(True, False)
                    card.setOnClickListener(self._click(lambda v, s=slug: _remove(s)))
                    clp = LinearLayout.LayoutParams(0, AndroidUtilities.dp(142), 1.0)
                    margin = AndroidUtilities.dp(4)
                    clp.setMargins(margin, margin, margin, margin)
                    line.addView(card, clp)
                while line.getChildCount() < 3:
                    line.addView(FrameLayout(ctx), LinearLayout.LayoutParams(0, 1, 1.0))
                grid.addView(line, LinearLayout.LayoutParams(-1, -2))
            scroll.addView(grid)
            glp = LinearLayout.LayoutParams(-1, 0, 1.0)
            root.addView(scroll, glp)

            def _deliver(_v):
                rows = []
                sent_b64 = []
                for _slug, gift, title in list(self._market_cart):
                    tpl = self._regular_entry_template(gift, title)
                    if tpl is not None:
                        rows.append({"b64": tpl["b64"], "title": title, "unique": True})
                        sent_b64.append((tpl["b64"], title))
                to_uid = int(_gv(fragment, "dialogId", 0) or 0)
                if to_uid == 0:
                    to_uid = int(_real_uid() or 0)
                if not rows:
                    self._toast("Не удалось подарить корзину")
                    return
                result = str(self._jvoid("deliverGiftBatch", ("str", "long"),
                                         (json.dumps(rows), to_uid)) or "")
                # Require an explicit success. _jvoid returns None for a bridge method that could
                # not be resolved or that threw, and the old "no FAIL in it" test read that empty
                # string as success — so the cart was emptied and the user was told the gifts were
                # on their way while nothing had been queued at all.
                if not result.startswith("ok"):
                    self.log("[market-cart] deliver failed: " + (result or "(no result)"))
                    self._toast("Не удалось подарить корзину")
                    return
                self._market_cart = []
                self._market_cart_mode = False
                self._hap("reveal", essential=True)
                # [market-visual] the queued outbox cannot render anything without
                # the author server - fire the core's local reveal for every row so
                # the gift message actually appears in the chat (the same path the
                # native gift sheet uses).
                _revealed = 0
                for _b64, _title in sent_b64:
                    try:
                        if self._core_reveal_sent(_b64, to_uid, ""):
                            _revealed += 1
                    except Exception:
                        pass
                try: self.log("[market-cart] reveal sent: %d/%d" % (_revealed, len(sent_b64)))
                except Exception: pass
                try: sheet_ref[0].dismiss()
                except Exception: pass
                self._toast("Подарки отправлены · %d" % _revealed)

            action = TextView(ctx)
            action.setText("Подарить всё · %d" % len(self._market_cart))
            action.setGravity(Gravity.CENTER)
            action.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 16)
            action.setTextColor(Theme.getColor(Theme.key_featuredStickers_buttonText))
            action_bg = GradientDrawable()
            action_bg.setCornerRadius(AndroidUtilities.dp(16))
            action_bg.setColor(Theme.getColor(Theme.key_featuredStickers_addButton))
            action.setBackground(self._ripple_bg(
                action_bg, Theme.getColor(Theme.key_featuredStickers_addButton)))
            action.setOnClickListener(self._click(_deliver))
            alp = LinearLayout.LayoutParams(-1, AndroidUtilities.dp(52))
            alp.topMargin = AndroidUtilities.dp(10)
            root.addView(action, alp)
            builder = BottomSheet.Builder(ctx)
            builder.setCustomView(root)
            sheet_ref[0] = builder.create()
            self._show_sheet_animated(sheet_ref[0], root)
        except Exception as e:
            self.log("[market-cart] sheet: " + _cause(e))

    def _install_catalog_hooks(self):
        """Lazily hook ResaleGiftsFragment.updateList/fillItems/onItemClick (cold path:
        these only fire while the catalog fragment is open — the profile is untouched)."""
        if getattr(self, "_cat_hooks_done", False):
            return True
        if MethodHook is None or getattr(self, "hook_method", None) is None:
            return False
        try:
            Frag = JavaClass.forName("org.telegram.ui.Gifts.ResaleGiftsFragment")
        except Exception as e:
            self.log("[cat] no ResaleGiftsFragment: " + _cause(e))
            return False
        refs = []
        try:
            for m in Frag.getDeclaredMethods():
                try:
                    nm = m.getName()
                except Exception:
                    continue
                try:
                    m.setAccessible(True)
                except Exception:
                    pass
                if nm == "updateList":
                    refs.append(self.hook_method(m, _CatUpdateHook(self)))
                elif nm == "fillItems":
                    refs.append(self.hook_method(m, _CatFillHook(self)))
                elif nm == "onItemClick":
                    refs.append(self.hook_method(m, _CatClickHook(self)))
        except Exception as e:
            self.log("[cat] hook err: " + _cause(e))
            return False
        self._cat_hook_refs = refs
        self._cat_hooks_done = True
        self.log("[cat] native hooks installed: " + str(len(refs)))
        return True

    def _open_catalog(self, nft_only=True):
        if jclass is None:
            return
        # kill any live auto-price loop from a previous constructor so it can't tick on a
        # dismissed sheet's views while the catalog is open
        try:
            self._ctor_value_loop_gen = getattr(self, "_ctor_value_loop_gen", 0) + 1
            self._nat_sheet = None
        except Exception:
            pass
        # close the «Мои подарки» sheet so the catalog fragment is on top
        for _attr in ("_gifts_sheet", "_catalog_sheet", "_nat_sheet"):
            try:
                s = getattr(self, _attr, None)
                if s is not None:
                    s.dismiss()
                    setattr(self, _attr, None)
            except Exception:
                pass
        # preload base gifts so the first frame isn't empty
        try:
            if not self._catalog_list():
                c = self._stars_ctrl()
                if c is not None:
                    c.loadStarGifts()
        except Exception:
            pass
        if self._install_catalog_hooks():
            try:
                self._cat_ctrl = None
                _NativeCatalog(self, nft_only=nft_only).show()
                return
            except Exception as e:
                self.log("[cat] native open failed, fallback: " + _cause(e))
        # fallback: homemade BottomSheet grid
        frag = get_last_fragment()
        ctx = frag.getParentActivity() if frag else None
        if not ctx:
            return
        gifts = self._catalog_list()
        if not gifts:
            self._toast("загружаю каталог…")
            run_on_ui_thread(lambda: self._open_catalog2(ctx), 1800)
            return
        run_on_ui_thread(lambda: self._show_catalog(ctx, gifts))

    def _open_catalog2(self, ctx):
        gifts = self._catalog_list()
        if not gifts:
            self._toast("Каталог пуст — открой профиль с подарками и попробуй снова")
            return
        self._show_catalog(ctx, gifts)

